// UA2 actual-effect kernels. Coefficients and scheduling belong to the trial config.
import {invariant} from '../runtime/hash.js';
import {safeCopy} from './foundation.js';
export const ULTIMATE_EFFECTS_VERSION='ua2-1-actual-effect-kernels-2';
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),finite=(x,f=0)=>Number.isFinite(x)?x:f;
export function insideShape(shape,p){if(!shape)return true;if(shape.kind==='target')return shape.targetId===p.id&&(!shape.origin||distance(shape.origin,p)<=shape.range+.01);if(['targets','linked'].includes(shape.kind))return shape.targetIds.includes(p.id);if(shape.kind==='circle'||shape.type==='circle')return distance(shape,p)<=shape.radius+.01;const o=shape.origin||shape,a=shape.direction||{x:shape.ux??1,y:shape.uy??0},length=Math.hypot(a.x,a.y)||1,dx=p.x-o.x,dy=p.y-o.y,along=(dx*a.x+dy*a.y)/length,side=Math.abs(dx*a.y-dy*a.x)/length;if(['line','segment','rectangle'].includes(shape.kind||shape.type)){if(shape.centered)return Math.abs(along)<=shape.length/2+.01&&side<=shape.width/2+.01;return along>=-.01&&along<=shape.length+.01&&side<=shape.width/2+.01;}if(['cone','fan'].includes(shape.kind||shape.type))return along>=0&&Math.hypot(dx,dy)<=shape.range+.01&&Math.atan2(side,along)<=shape.halfAngle+.00001;throw Error('Unsupported frozen ultimate shape');}
function slowArea(target,tick){const xs=(target.slows||[]).filter(s=>s.untilTick>tick),points=[tick,...xs.map(s=>s.untilTick)].sort((a,b)=>a-b);let n=0;for(let i=1;i<points.length;i++)n+=(points[i]-points[i-1])*xs.filter(s=>s.untilTick>points[i-1]).reduce((m,s)=>Math.max(m,s.value),0);return n;}
export function createUltimateEffects(game,{statusAdapter=null}={}){
 invariant(game.phase==='battle'&&game._v10PipelineInstalled,'Started protected engine required');let groups={},journal=[],sequence=0,ended=false;
 const now=()=>game.tickCount,find=id=>[...game.units,...game.enemies].find(u=>u.id===id),live=u=>u&&u.hp>0;
 const log=(type,g,detail)=>journal.push({id:`${game.battleId}:ultimate-trigger:${++sequence}`,type,tick:now(),rootActionId:g.rootActionId,skillId:g.skillId,sourceId:g.sourceId,...detail});
 const inShape=(shape,t)=>insideShape(shape,t)&&(shape?.kind!=='linked'||game.formationLinks?.[t.id]?.sourceId===shape.sourceId);
 const groupAlive=g=>!ended&&game.phase==='battle'&&now()<g.untilTick&&live(find(g.sourceId));
 const groupTargetEligible=(e,t)=>live(t)&&(e.range===undefined||distance(find(e.sourceId),t)<=e.range+.01)&&inShape(e.shape,t)&&(e.kind!=='ward'||t.barrier&&t.barrier.amount>0&&t.barrier.untilTick>now()&&t.barrier.ownerId===e.sourceId&&t.barrier._ua2UltimateRootActionId===e.rootActionId);
 function register(e){const key=e.rootActionId+':'+e.sharedBudgetKey;invariant(!groups[key],'Duplicate shared effect group');invariant(Array.isArray(e.targetIds)&&e.targetIds.length>0&&e.targetIds.length<=2&&new Set(e.targetIds).size===e.targetIds.length&&e.targetIds.every(id=>find(id)?.team==='ally'),'Bounded ally group required');invariant(Number.isFinite(e.totalBudget)&&e.totalBudget>0&&Number.isInteger(e.durationTicks)&&e.durationTicks>0,'Finite bounded group required');if(e.kind==='protection')invariant(Number.isFinite(e.rate)&&e.rate>0&&e.rate<=.55,'Invalid protection rate');else invariant(e.totalBudget===1&&e.charges===1,'Shared prevention is exactly one charge');const eligibleTargetIds=e.targetIds.filter(id=>groupTargetEligible(e,find(id)));invariant(eligibleTargetIds.length>0,'No effective frozen group member');groups[key]={...safeCopy(e),originalTargetIds:[...e.targetIds],targetIds:eligibleTargetIds,id:key,remainingBudget:e.totalBudget,untilTick:now()+e.durationTicks,consumed:0};return {registeredBudget:e.totalBudget,groupId:key,eligibleTargetIds,originalTargetIds:[...e.targetIds]};}
 const provider={id:'ua2-ultimate-protection',candidates({target,incoming,mitigated,attacker,kind,action,tick}){if(target.team!=='ally')return [];return Object.values(groups).filter(g=>g.kind==='protection'&&groupAlive(g)&&g.targetIds.includes(target.id)&&inShape(g.shape,target)&&g.remainingBudget>0&&(!g.rangedOnly||action.ranged===true||['arrow','mage_bolt','arcane_bolt','fire_bolt','frost_bolt'].includes(kind))).map(g=>({id:g.id,sourceId:g.sourceId,targetId:target.id,reduction:Math.min(g.remainingBudget,mitigated*g.rate,Math.max(0,mitigated-.45*incoming)),consume(n){invariant(Number.isFinite(n)&&n>0&&n<=g.remainingBudget+1e-8,'Invalid actual protection consumption');const before=g.remainingBudget;g.remainingBudget=Math.max(0,before-n);g.consumed+=n;const barrier=target.barrier&&tick<target.barrier.untilTick?target.barrier.amount:0,hpAvoided=Math.max(0,Math.min(target.hp,Math.max(0,mitigated-barrier))-Math.min(target.hp,Math.max(0,mitigated-n-barrier)));log('protection',g,{targetId:target.id,attackerId:attacker.id,incoming,mitigated,actual:n,hpAvoided,budgetBefore:before,budgetAfter:g.remainingBudget});}}));}};
 game._v10ProtectionProviders.push(provider);
 game.ultimateProtectionGroups=()=>safeCopy(Object.values(groups).filter(g=>g.kind==='protection'&&groupAlive(g))); // observational, no expiry or journal writes
 if(statusAdapter?.registerPreventionProvider)statusAdapter.registerPreventionProvider('ua2-shared-ward',({targetId,sourceId,statusType})=>{const candidates=Object.values(groups).filter(g=>g.kind==='ward'&&groupAlive(g)&&g.remainingBudget>0&&g.targetIds.includes(targetId)&&inShape(g.shape,find(targetId))).sort((a,b)=>a.sourceId-b.sourceId||a.id.localeCompare(b.id));for(const g of candidates){const t=find(targetId);if(!t.barrier||t.barrier.ownerId!==g.sourceId||t.barrier._ua2UltimateRootActionId!==g.rootActionId||t.barrier.amount<=0||now()>=t.barrier.untilTick)continue;g.remainingBudget=0;g.consumed=1;log('prevention',g,{targetId,statusSourceId:sourceId,statusType,actual:1,budgetBefore:1,budgetAfter:0});return {prevented:true,rootActionId:g.rootActionId};}return {prevented:false};});
 function apply(e){invariant(e&&typeof e.eventId==='string'&&Number.isFinite(e.amount)&&e.amount>=0,'Finite effect intent required');const s=find(e.sourceId),t=find(e.targetId);invariant(s&&t,'Frozen source/target disappeared');let before=0,after=0,maximum=0,reason=null,detail={};const groupEffect=['protection','ward'].includes(e.kind),blocked=game.phase!=='battle'?'battle-ended':!live(s)?'dead-source-or-target':groupEffect?(!Array.isArray(e.targetIds)||!e.targetIds.some(id=>groupTargetEligible(e,find(id)))?'no-effective-frozen-group-member':null):!live(t)?'dead-source-or-target':e.range!==undefined&&distance(s,t)>e.range+.01?'out-of-range':!inShape(e.shape,t)?'outside-frozen-shape':null;
 if(blocked)reason=blocked;
 else if(e.kind==='damage'){before=t.hp;maximum=before;game.resolveDamageAction(()=>game.hit(s,t,e.amount,e.damageType==='magic'?'arcane_bolt':'hit',{eventId:e.eventId,rootActionId:e.rootActionId,skillId:e.skillId,ownerKind:'unit',actionType:'unit_skill',skillKind:'ultimate',effectKind:'damage',damageType:e.damageType||'physical',canCrit:false,enhancedBasic:false,sourceKind:e.derived?'derived':'ultimate',paidCast:false,dot:e.derived===true}));after=t.hp;}
 else if(e.kind==='heal'){before=t.hp;maximum=t.maxHp-before;game.heal(t,e.amount,s,{sourceKind:'ultimate_special_heal'});after=t.hp;}
 else if(e.kind==='shield'){before=t.barrier&&now()<t.barrier.untilTick?t.barrier.amount:0;maximum=Math.max(0,e.amount-before);game.grantBarrier(s,t,e.amount,(e.durationTicks??Math.ceil(e.duration*60))/60);after=t.barrier&&now()<t.barrier.untilTick?t.barrier.amount:0;if(after>before)t.barrier._ua2UltimateRootActionId=e.rootActionId;}
 else if(e.kind==='cleanse'){invariant(statusAdapter,'Status cleanse capability required');maximum=1;const removed=statusAdapter.cleanse(t.id,{max:1}).removed;after=removed.length;detail={removedIds:removed.map(x=>x.id)};}
 else if(e.kind==='slow'){invariant(Number.isFinite(e.value)&&e.value>0&&Number.isInteger(e.durationTicks)&&e.durationTicks>0,'Bounded slow required');before=slowArea(t,now());maximum=Math.min(.25,e.value)*(t.type==='boss'?.5:1)*e.durationTicks;const slowSourceId=`ua2:${s.id}:${e.rootActionId}`;const old=safeCopy(t.slows||[]);if(now()<finite(t.slowImmuneUntilTick)){reason='slow-immunity';}else game.applySlow({id:slowSourceId},t,e.value,e.durationTicks/60);after=slowArea(t,now());if(after<before){t.slows=old;after=before;reason='stronger-existing-slow';}detail={unit:'magnitude-ticks',durationTicks:e.durationTicks,bossFactor:t.type==='boss'?.5:1,engineSlowSourceId:slowSourceId};}
 else if(e.kind==='attackDelay'){const requestedDelta=e.amount*game.attackHaste(t);before=t.cd;const endpoint=before+requestedDelta;maximum=endpoint-before;if(t.type==='boss')reason='boss-pattern-immune';else if(t.attacks!==e.expectedAttackSequence)reason='attack-sequence-changed';else if(t._v10FrostSeal&&now()<t._v10FrostSeal.until)reason='existing-frost-seal';else if(now()<Math.max(finite(t._v10SealImmuneUntil),finite(t._v10WatchImmuneUntil),finite(t._ua2DelayImmuneUntil))||t._ua2DelaySequence===t.attacks)reason='delay-immunity';else{t.cd=endpoint;t._ua2DelayImmuneUntil=now()+e.immunityTicks;t._ua2DelaySequence=t.attacks;}after=t.cd;detail={unit:'cooldown-seconds',attackSequence:t.attacks,requestedDelaySeconds:e.amount,requestedCooldownDelta:requestedDelta,representableEndpoint:endpoint};}
 else if(e.kind==='move'){invariant(e.destination&&Number.isFinite(e.destination.x)&&Number.isFinite(e.destination.y)&&Number.isFinite(e.maxDistance),'Frozen bounded destination required');maximum=e.maxDistance;const d=distance(s,e.destination);if(d>maximum+.01||e.destination.x<75||e.destination.x>830||e.destination.y<128||e.destination.y>477)reason='invalid-destination';else{const prior={x:s.x,y:s.y};s.x=e.destination.x;s.y=e.destination.y;s.move=0;after=d;detail={from:prior,to:{x:s.x,y:s.y},unit:'distance'};}}
 else if(['protection','ward'].includes(e.kind)){detail=register(e);detail.registrationOnly=true;}
 else throw Error('Unsupported ultimate effect kind');
 const actual=e.kind==='damage'?before-after:after-before;invariant(Number.isFinite(actual)&&actual>=-1e-8&&actual<=maximum+1e-7,'Invalid actual effect delta');return {eventId:e.eventId,targetId:e.targetId,sourceId:e.sourceId,kind:e.kind,tick:now(),before,after,actual:Math.max(0,actual),maximum,reason,...detail};
 }
 function afterTick(){if(game.phase!=='battle')ended=true;}
 const snapshot=()=>({version:ULTIMATE_EFFECTS_VERSION,battleId:game.battleId,groups:safeCopy(groups),journal:safeCopy(journal),sequence,ended});
 const restore=s=>{invariant(s.version===ULTIMATE_EFFECTS_VERSION&&s.battleId===game.battleId,'Foreign ultimate effect state');groups=safeCopy(s.groups);journal=safeCopy(s.journal);sequence=s.sequence;ended=s.ended;};
 game._v10CheckpointParticipants.push({id:'ua2-ultimate-effects',capture:snapshot,restore});
 return {apply,snapshot,restore,afterTick};
}
